import{_ as o,o as e,c as n,a5 as a}from"./chunks/framework.Cooo9kuv.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"快速创建文件夹的几种方式","日期":"2026-04-13T00:00:00.000Z","修改日期":"2026-04-13T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["win系统问题"],"标签":["创建文件夹","快速创建文件夹"]},"headers":[],"relativePath":"md/win系统问题/快速创建文件夹的几种方式.md","filePath":"md/win系统问题/快速创建文件夹的几种方式.md"}'),p={name:"md/win系统问题/快速创建文件夹的几种方式.md"};function r(s,t,l,i,u,d){return e(),n("div",null,[...t[0]||(t[0]=[a('<h3 id="新建文件夹菜单放在右键菜单一级顶层" tabindex="-1">新建文件夹菜单放在右键菜单一级顶层 <a class="header-anchor" href="#新建文件夹菜单放在右键菜单一级顶层" aria-label="Permalink to &quot;新建文件夹菜单放在右键菜单一级顶层&quot;">​</a></h3><p>在Win10系统下，默认新建文件夹需要从右键——新建——文件夹来创建，这样需要点两次比较不方便，如果你经常创建文件夹，那么可以通过下面分享的方法把新建文件夹菜单放在右键菜单一级顶层。<br> 方法如下：</p><p>1、新建一个文本文档，将下面的文本复制粘贴到文件，保存，使用记事本或其它文本编辑器均可。</p><p>Windows Registry Editor Version 5.00</p><p>[HKEY_CLASSES_ROOT\\Directory\\Background\\shell\\Windows.newfolder]<br> &quot;CanonicalName&quot;=&quot;{E44616AD-6DF1-4B94-85A4-E465AE8A19DB}&quot;<br> &quot;CommandStateHandler&quot;=&quot;{3756e7f5-e514-4776-a32b-eb24bc1efe7a}&quot;<br> &quot;CommandStateSync&quot;=&quot;&quot;<br> &quot;Description&quot;=&quot;@shell32.dll,-31237&quot;<br> &quot;ImpliedSelectionModel&quot;=dword:00000004<br> &quot;InvokeCommandOnSelection&quot;=dword:00000000<br> &quot;Icon&quot;=&quot;shell32.dll,-319&quot;<br> &quot;MUIVerb&quot;=&quot;@shell32.dll,-31236&quot;<br> &quot;Position&quot;=&quot;Top&quot;</p><p>2、然后将文件扩展名由.txt更改为.reg，名称无所谓。如果看不到.txt扩展名，打开“此电脑”，点击查看，勾选“文件扩展名”，也可以在文件夹选项中勾选。</p><p>3、双击文件，点击“是”按钮确定导入，无需其它操作，新建文件夹菜单项会加入到桌面及文件夹背景的右键菜单。</p><p>4、如果不满意它的位置，可以修改上述文本中Position后的文本，比如改为bottom后导入，新建文件夹菜单项将显示在底部。</p><p>5、Icon修改图标，从网络上下载或使用集成在exe、dll中的均可。MUIVerb修改它在菜单中显示的名称。</p><p>6、删除此菜单项，在开始菜单或运行中输入regedit，打开注册表编辑器，展开到HKEY_CLASSES_ROOT\\Directory\\Background\\shell，删除Windows.newfolder即可。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250625073436175080807666290.jpeg" alt="IMG_256"></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250625073436175080807622127.jpeg" alt="IMG_257"></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250625073436175080807693055.jpeg" alt="IMG_258"></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250625073436175080807652010.png" alt="IMG_259"></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250625073436175080807690323.jpeg" alt="IMG_260"></p><h3 id="快捷键创建文件夹的方法" tabindex="-1">快捷键创建文件夹的方法： <a class="header-anchor" href="#快捷键创建文件夹的方法" aria-label="Permalink to &quot;快捷键创建文件夹的方法：&quot;">​</a></h3><p>第一种方式：</p><p>在电脑桌面空白处，鼠标右击，然后同时按住键盘的W和F，即可自动创建新文件夹。</p><p>第二种方式：</p><p>或者按下“Ctrl + Shift + N”组合键，也可以快速创建一个新文件夹。</p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/1898.html" target="_blank" rel="noreferrer">https://www.softbangong.com/1898.html</a></p>',22)])])}const m=o(p,[["render",r]]);export{_ as __pageData,m as default};
